/usr/bin/bash -lc "/runtime/node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';

const source = readFileSync('/workspace/src/session.js', 'utf8');
const moduleUrl = 'data:text/javascript;base64,' + Buffer.from(source).toString('base64');
const { createResource } = await import(moduleUrl);

const results = [false, false, true];
const scheduled = [];
const cancelled = new Set();
const publications = [];
const host = {
  check() { return Promise.resolve(results.shift()); },
  schedule(callback) { const id = scheduled.length; scheduled.push(callback); return id; },
  cancel(id) { cancelled.add(id); },
  publish(state) { publications.push(state); }
};
const resource = createResource(host, 'download', 'dig-42');
const turn = () => new Promise(resolve => queueMicrotask(resolve));

resource.start();
await turn();
assert.equal(resource.snapshot().checkCount, 1);
assert.equal(resource.snapshot().retryScheduled, true);
assert.equal(resource.snapshot().completed.length, 0);

scheduled.shift()();
await turn();
assert.equal(resource.snapshot().checkCount, 2);
assert.equal(resource.snapshot().retryScheduled, true);
assert.equal(resource.snapshot().completed.length, 0);

scheduled.shift()();
await turn();
assert.equal(resource.snapshot().checkCount, 3);
assert.equal(resource.snapshot().retryScheduled, false);
assert.deepEqual(resource.snapshot().completed, ['dig-42']);
assert.equal(scheduled.length, 0);
assert.equal(cancelled.size, 0);
assert.ok(publications.length >= 6);

console.log('pending → pending → ready: PASS');
NODE"

